package com.prem.anagram;
import java.util.*;
public class BinaryTreeTraversals {public static class Node{public int data;public Node left,right;public Node(int d){data=d;}}public static List<Integer> inorder(Node n){List<Integer>r=new ArrayList<>();in(n,r);return r;}private static void in(Node n,List<Integer>r){if(n==null)return;in(n.left,r);r.add(n.data);in(n.right,r);}public static List<Integer> preorder(Node n){List<Integer>r=new ArrayList<>();pre(n,r);return r;}private static void pre(Node n,List<Integer>r){if(n==null)return;r.add(n.data);pre(n.left,r);pre(n.right,r);}public static List<Integer> postorder(Node n){List<Integer>r=new ArrayList<>();post(n,r);return r;}private static void post(Node n,List<Integer>r){if(n==null)return;post(n.left,r);post(n.right,r);r.add(n.data);}}
